tool_input.command:
node -e '
const fs=require("fs");
const html=fs.readFileSync("game.html","utf8");
const m=html.match(/<script>([\s\S]*)<\/script>/);
if(!m){console.log("NO SCRIPT");process.exit(1);}
const src=m[1];
eval(src);
const res=runTests();
res.forEach((r,i)=>console.log((r.ok?"PASS":"FAIL")+" "+(i+1)+". "+r.name));
console.log(res.filter(r=>r.ok).length+"/"+res.length+" passed");
const b1=runBenchmark("1337"), b2=runBenchmark("1337");
console.log("bench1",b1.hash,"turn",b1.turn,"pop",b1.pop,"research",b1.research,"score",b1.score,"status",b1.over);
console.log("bench2",b2.hash,"identical:",b1.hash===b2.hash);
// winnable/losable probe
const w=simulate("1337",60);
console.log("policy@60: pop",w.cols.length,"over",w.over?JSON.stringify({win:w.over.win,review:!!w.over.review}):"none","food",w.res.food,"water",w.res.water);
const l=(()=>{const st=newGame("1337"); for(let i=0;i<80;i++){ if(st.over&&!st.over.review)break; endTurn(st,0);} return st;})();
console.log("no-policy run: pop",l.cols.length,"turn",l.turn,"over",l.over?l.over.win:"none");
'

